# 1. Validar Groq API (Gratis, rápido, sin Qwen/Alibaba)
groq_key = os.environ.get("GROQ_API_KEY")
if groq_key:
    body = json.dumps({
        "model": "llama-3.1-8b-instant",
        "messages": [{"role": "user", "content": "di ok"}],
        "max_tokens": 3
    }).encode()
    req = urllib.request.Request(
        "https://api.groq.com/openai/v1/chat/completions",
        data=body,
        headers={"Authorization": f"Bearer {groq_key}", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            d = json.load(r)
            print("✅ GROQ API OK:", d["choices"][0]["message"]["content"].strip())
    except Exception as e:
        print("❌ GROQ FALLO:", str(e)[:100])
else:
    print("⚠️ GROQ_API_KEY no encontrada")

# 2. Validar NVIDIA NIM (excluyendo Qwen/Alibaba)
nvidia_key = os.environ.get("NVIDIA_API_KEY")
if nvidia_key:
    # Modelo seguro: meta/llama-3.1-8b-instruct o mistralai/mixtral-8x7b-instruct-v0.1
    body = json.dumps({
        "model": "meta/llama-3.1-8b-instruct",
        "messages": [{"role": "user", "content": "di ok"}],
        "max_tokens": 3
    }).encode()
    req = urllib.request.Request(
        "https://integrate.api.nvidia.com/v1/chat/completions",
        data=body,
        headers={"Authorization": f"Bearer {nvidia_key}", "Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as r:
            d = json.load(r)
            print("✅ NVIDIA NIM OK:", d["choices"][0]["message"]["content"].strip())
    except Exception as e:
        print("❌ NVIDIA FALLO:", str(e)[:100])
else:
    print("⚠️ NVIDIA_API_KEY no encontrada")

# 3. Verificar existencia del registro unificado y estructura open-school
base_path = r"C:\Users\USER\belentani-repos-master\open-school"
registry_path = os.path.join(base_path, "open-data", "unified-campus-registry.json")
client_public_data = os.path.join(base_path, "client", "public", "open-data")

print("\n--- ESTADO DE UNIFICACIÓN ---")
if os.path.exists(registry_path):
    print(f"✅ Registro encontrado en: {registry_path}")
    with open(registry_path, 'r', encoding='utf-8') as f:
        data = json.load(f)
        print(f"   Total escuelas mapeadas: {len(data.get('schools', []))}")
        print(f"   Total recursos: {data.get('total_resources', 'N/A')}")
else:
    print("⚠️ Registro unificado no encontrado en open-data")

if not os.path.exists(client_public_data):
    os.makedirs(client_public_data, exist_ok=True)
    print(f"✅ Creado directorio cliente: {client_public_data}")

# Copiar el registro a la carpeta pública del cliente si existe
if os.path.exists(registry_path) and os.path.exists(client_public_data):
    import shutil
    shutil.copy2(registry_path, os.path.join(client_public_data, "unified-campus-registry.json"))
    print("✅ Registro copiado a client/public/open-data/ para consumo de la UI")"}

